const IdentityProviderButtons = ({ identityProviderList, redirectTarget }: Props) => {
  const t = useTranslate();

  const handleSignInWithIdentityProvider = async (identityProvider: IdentityProvider) => {
    if (identityProvider.type === IdentityProvider_Type.OAUTH2) {
      const redirectUri = absolutifyLink(ROUTES.AUTH_CALLBACK);
      const oauth2Config = identityProvider.config?.config?.case === "oauth2Config" ? identityProvider.config.config.value : undefined;
      if (!oauth2Config) {
        toast.error("Identity provider configuration is invalid.");
        return;
      }

      try {
        // Generate and store secure state parameter with CSRF protection
        // Also generate PKCE parameters (code_challenge) for enhanced security if available
        const { state, codeChallenge } = await storeOAuthState(identityProvider.name, "signin", redirectTarget);

        // Build OAuth authorization URL with secure state
        // Include PKCE if available (requires HTTPS/localhost for crypto.subtle)
        // Using S256 (SHA-256) as the code_challenge_method per RFC 7636
        let authUrl = `${oauth2Config.authUrl}?client_id=${
          oauth2Config.clientId
        }&redirect_uri=${encodeURIComponent(redirectUri)}&state=${state}&response_type=code&scope=${encodeURIComponent(
          oauth2Config.scopes.join(" "),
        )}`;

        // Add PKCE parameters if available
        if (codeChallenge) {
          authUrl += `&code_challenge=${codeChallenge}&code_challenge_method=S256`;
        }

        window.location.href = authUrl;
      } catch (error) {
        handleError(error, toast.error, {
          context: "Failed to initiate OAuth flow",
          fallbackMessage: "Failed to initiate sign-in. Please try again.",
        });
      }
    }
  };

  return (
    <div className="flex w-full flex-col gap-2">
      {identityProviderList.map((identityProvider) => (
        <Button key={identityProvider.name} variant="outline" onClick={() => handleSignInWithIdentityProvider(identityProvider)}>
          {t("auth.continue-with", { provider: identityProvider.title })}
        </Button>
      ))}
    </div>
  );
};

const SignIn = () => {
  const t = useTranslate();
  const { generalSetting: instanceGeneralSetting } = useInstance();
  const [searchParams] = useSearchParams();
  const { identityProviderList, isLoading: identityProvidersLoading } = useIdentityProviderList();
  const redirectTarget = getSafeRedirectPath(searchParams.get(AUTH_REDIRECT_PARAM));
  const signUpPath = appendSearchParams(ROUTES.AUTH_SIGNUP, searchParams);

  const passwordAuthAllowed = !instanceGeneralSetting.disallowPasswordAuth;
  const hasIdentityProviders = identityProviderList.length > 0;

  // Shared by the subtitle and the body branch so they can't disagree.
  const showAuthOptions = identityProvidersLoading || passwordAuthAllowed || hasIdentityProviders;

  return (
    <AuthPageLayout title={t("common.sign-in")} subtitle={showAuthOptions ? t("auth.welcome-back") : undefined}>
      {identityProvidersLoading ? (
        <AuthOptionsLoading />
      ) : showAuthOptions ? (
        <>
          {hasIdentityProviders && <IdentityProviderButtons identityProviderList={identityProviderList} redirectTarget={redirectTarget} />}
          {hasIdentityProviders && passwordAuthAllowed && (
            <div className="my-4 flex items-center gap-3 text-xs uppercase tracking-wider text-muted-foreground">
              <div className="flex-1">
                <Separator />
              </div>
              {t("common.or")}
              <div className="flex-1">
                <Separator />
              </div>
            </div>
          )}
          {passwordAuthAllowed && <PasswordSignInForm redirectPath={redirectTarget} />}
          {passwordAuthAllowed && !instanceGeneralSetting.disallowUserRegistration && (
            <AuthLinkPrompt prompt={t("auth.sign-up-tip")} to={signUpPath} label={t("common.sign-up")} />
          )}
        </>
      ) : (
        <AuthEmptyState
          icon={<LockIcon className="h-5 w-5" />}
          title={t("auth.signin-unavailable-title")}
          description={t("auth.signin-unavailable-description")}
        >
          <Link to={ROUTES.AUTH_ADMIN} className="mt-3 inline-flex items-center gap-1 text-sm text-primary hover:underline" viewTransition>
            {t("auth.admin-sign-in")}
            <ArrowRightIcon className="h-3.5 w-3.5" />
          </Link>
        </AuthEmptyState>
      )}
    </AuthPageLayout>
  );
};

